// Benchmark for the per-cell pending-event sort performed in
// simulation.cpp::simulation_state::run() (the "sort" step of the enqueue
// task, `ska_sort(pending_events_[i], (time, target, weight))`).
//
// Data shape: the pending events of each cell are generated by emulating the
// exchange -> make_event_queues pipeline of the communicator, using
// append_events_from_domain (copied into event_dispatch.hpp) and local
// domains only (no remote/external spikes, no MPI). This yields one
// std::vector<spike_event> per local cell, which is a concatenation of runs,
// one run per (source, connection) chunk; each run is time-sorted because
// spike times are ascending within a source.
//
// Candidates:
//   - std::sort (comparison baseline)
//   - ska_sort  (current production algorithm)
//   - pdqsort   (Removed, not competetive)
//   - run_merge (the "specialized" hypothesis: merge the sorted runs directly
//     instead of sorting, using the existing merge machinery)
//
// Only the sort work is timed; merge_cell_events is not benchmarked here.

#include <algorithm>
#include <cstddef>
#include <cstdio>
#include <random>
#include <set>
#include <vector>

#include <benchmark/benchmark.h>

#include <arbor/assert.hpp>
#include <arbor/common_types.hpp>
#include <arbor/spike.hpp>
#include <arbor/spike_event.hpp>

#include "connection.hpp"
#include "communication/connection_list.hpp"
#include "merge_events.hpp"
#include "util/range.hpp"
#include "util/tourney_tree.hpp"
#include "util/skasort.hpp"

using namespace arb;

namespace {

// Precondition (as in append_events_from_domain): the spike slice must be
// sorted by source, and every spike source in the slice must have at least
// one connection to a local cell (i.e. be present in the domain's
// first_occurence table; the lookup uses lut.at).
//
// If the spike times of a source are ascending, every appended run is sorted
// by the full event key (time, target, weight), since target and weight are
// constant within a (source, connection) chunk.
template<typename S>
void append_events_from_domain(const connections_list& cons, size_t dom,
                               const S& spikes,
                               std::vector<pse_vector>& queues,
                               std::vector<std::vector<std::size_t>>& run_starts) {
    const auto& lut = cons.first_occurence[dom];
    auto send = spikes.end();
    auto scur = spikes.begin();
    arb_assert(util::is_sorted_by(spikes, [](auto it) { return it.source; }));
    while (scur < send) {
        auto sfst = scur;
        auto src = scur->source;
        const auto& [cfst, clst] = lut.at(std::bit_cast<std::uint64_t>(src));
        for (auto cidx = cfst; cidx < clst; ++cidx) {
            auto iod = cons.idx_on_domain[cidx];
            auto dst = cons.dests[cidx];
            auto del = cons.delays[cidx];
            auto wgt = cons.weights[cidx];
            run_starts[iod].push_back(queues[iod].size());
            for (scur = sfst; (scur < send) && (scur->source == src); ++scur) {
                queues[iod].emplace_back(dst, scur->time + del, wgt);
            }
        }
    }
}

constexpr cell_size_type N_SRC_SITES    = 4;   // spike sources (lid) per global cell
constexpr cell_size_type N_TGT_PER_CELL = 3;   // target lids per local cell
constexpr double EPOCH_MS               = 5.0; // epoch length [ms] (~ half a 10ms min delay)

// Expected number of spikes fired by each (present) source site in the epoch.
// Chosen so that per-cell queues (≈ fan_in * SPIKES_LAMBDA) span the size range
// where the sort choice matters (from the ~16-element ska_sort fallback
// threshold up to a few thousand). This is a stress value: the shape of the
// queue (a concatenation of time-sorted runs) is what is under test, not the
// absolute spike count.
constexpr double SPIKES_LAMBDA              = 8.0;
constexpr std::size_t MAX_SPIKES_PER_SOURCE = 32;

auto full_key(const spike_event& e) {
    return std::tie(e.time, e.target, e.weight);
}

// The data needed for one parameter set, generated once before the timing loop.
struct payload {
    connections_list cons;
    std::vector<pse_vector> queues;                    // pending_events_ per local cell
    std::vector<std::vector<std::size_t>> run_starts;  // per cell: start of each appended run

    std::size_t n_local_cells = 0;
    std::size_t total_events = 0;
    std::size_t in_order_pairs = 0;
    std::size_t adjacent_pairs = 0;
    std::size_t max_queue_size = 0;
};

payload generate_payload(cell_size_type num_local_cells, std::size_t fan_in, std::size_t num_domains) {
    payload p;
    p.n_local_cells = num_local_cells;

    // Deterministic seed derived from the parameters.
    std::mt19937_64 gen(0xC0FFEEull ^ static_cast<std::uint64_t>(num_local_cells)
                        ^ (static_cast<std::uint64_t>(fan_in) << 32)
                        ^ (static_cast<std::uint64_t>(num_domains) << 16));

    // "This rank" owns the local cells with local index 0..num_local_cells-1
    // (gids 0..num_local_cells-1, i.e. on domain 0 of the global gid space).
    const cell_size_type num_total_cells = num_local_cells * num_domains;

    // Connections: each local cell has `fan_in` connections to random source
    // cells across the whole network, with random target lid/weight/delay.
    // Connections are split by source domain, mirroring
    // communicator::update_connections.
    std::vector<std::vector<connection>> by_src_domain(num_domains);
    std::uniform_int_distribution<cell_gid_type> src_dist(0, num_total_cells - 1);
    std::uniform_int_distribution<cell_lid_type> lid_dist(0, N_SRC_SITES - 1);
    std::uniform_int_distribution<cell_lid_type> tgt_dist(0, N_TGT_PER_CELL - 1);
    std::uniform_real_distribution<float> weight_dist(-2.0f, 2.0f);
    std::uniform_real_distribution<float> delay_dist(0.0f, 1.0f);

    for (cell_size_type tgt = 0; tgt < num_local_cells; ++tgt) {
        for (std::size_t i = 0; i < fan_in; ++i) {
            cell_gid_type src_gid = src_dist(gen);
            auto dom = src_gid / num_local_cells;
            by_src_domain[dom].emplace_back(connection{
                .source = {.gid = src_gid, .index = lid_dist(gen)},
                .target = tgt_dist(gen),
                .weight = weight_dist(gen),
                .delay = delay_dist(gen),
                .index_on_domain = tgt
            });
        }
    }

    p.cons.make(by_src_domain);

    // Spikes: every source site that has at least one connection to a local
    // cell (i.e. is present in the domain's first_occurence table) fires
    // Poisson(lambda) times in the epoch, with ascending times. Spikes are
    // partitioned by source domain, like the gathered_vector layout produced by
    // the all-to-all exchange.
    std::vector<std::vector<spike>> spikes_by_dom(num_domains);
    std::poisson_distribution<std::size_t> poisson(SPIKES_LAMBDA);
    std::uniform_real_distribution<double> time_dist(0.0, EPOCH_MS);

    for (std::size_t dom = 0; dom < num_domains; ++dom) {
        const auto& lut = p.cons.first_occurence[dom];
        for (const auto& [key, range]: lut) {
            auto src = std::bit_cast<cell_member_type>(key);
            auto n_spikes = std::min<std::size_t>(poisson(gen), MAX_SPIKES_PER_SOURCE);
            if (n_spikes == 0) continue;

            std::vector<time_type> times(n_spikes);
            for (auto& t: times) t = time_dist(gen);
            std::sort(times.begin(), times.end()); // ascending within source

            for (auto t: times) {
                spikes_by_dom[dom].emplace_back(src, t);
            }
        }
    }
    for (auto& v: spikes_by_dom) {
        // Satisfies the is_sorted_by(source) invariant of
        // append_events_from_domain.
        std::sort(v.begin(), v.end());
    }

    // Dispatch into per-cell queues, recording the start index of each
    // appended run per cell.
    p.queues.resize(num_local_cells);
    p.run_starts.resize(num_local_cells);
    for (std::size_t dom = 0; dom < num_domains; ++dom) {
        auto& v = spikes_by_dom[dom];
        append_events_from_domain(p.cons, dom,
                                  util::make_range(v.data(), v.data() + v.size()),
                                  p.queues, p.run_starts);
    }

    // Statistics + sanity checks.
    double max_delay = 0.0;
    for (auto d: p.cons.delays) max_delay = std::max(max_delay, double(d));
    for (std::size_t c = 0; c < num_local_cells; ++c) {
        auto& q = p.queues[c];
        p.total_events += q.size();
        p.max_queue_size = std::max(p.max_queue_size, q.size());
        for (std::size_t i = 1; i < q.size(); ++i) {
            ++p.adjacent_pairs;
            if (full_key(q[i - 1]) < full_key(q[i])) ++p.in_order_pairs;
        }
        for (const auto& e: q) {
            arb_assert(e.time >= 0 && e.time <= EPOCH_MS + max_delay);
        }
        // Every run (and the whole queue) must be sorted by the full key.
        auto& rs = p.run_starts[c];
        for (std::size_t r = 0; r < rs.size(); ++r) {
            auto b = q.begin() + rs[r];
            auto e = (r + 1 < rs.size())? q.begin() + rs[r + 1] : q.end();
            arb_assert(std::is_sorted(b, e));
        }
        arb_assert(std::is_sorted(q.begin(), q.end()));
        for (std::size_t r = 0; r + 1 < rs.size(); ++r) {
            arb_assert(rs[r] < rs[r + 1]);
        }
        if (!rs.empty()) arb_assert(rs.back() < q.size());
    }
    arb_assert(p.total_events > 0);

    // One-shot shape report per unique parameter set (to stderr).
    {
        auto key = num_local_cells * 1'000'000 + fan_in * 100 + num_domains;
        static std::set<std::uint64_t> reported;
        if (reported.insert(key).second) {
            auto frac = p.adjacent_pairs == 0? 1.0
                       : static_cast<double>(p.in_order_pairs) / static_cast<double>(p.adjacent_pairs);
            std::fprintf(stderr,
                         "[shape] cells=%zu fan_in=%zu domains=%zu | total_events=%zu "
                         "events/cell=%.1f max_events/cell=%zu runs/cell(0)=%zu "
                         "in_order_adjacent_pairs=%.4f\n",
                         static_cast<std::size_t>(num_local_cells), fan_in, num_domains, p.total_events,
                         static_cast<double>(p.total_events) / static_cast<double>(num_local_cells),
                         p.max_queue_size, p.run_starts[0].size(), frac);
        }
    }
    return p;
}

// Reverse every run of a (clone of the) cell queues, destroying the
// time-sorted order within runs while keeping the run boundaries. This is
// the worst case for run-merging: the run *ranges* are still key-sorted, but
// no run is internally sorted.
void shuffle_runs(payload& p) {
    for (std::size_t c = 0; c < p.queues.size(); ++c) {
        auto& q = p.queues[c];
        const auto& rs = p.run_starts[c];
        for (std::size_t r = 0; r < rs.size(); ++r) {
            auto b = q.begin() + rs[r];
            auto e = (r + 1 < rs.size())? q.begin() + rs[r + 1] : q.end();
            std::reverse(b, e);
        }
    }
}

std::vector<event_span> make_run_spans(const payload& p, std::size_t cell) {
    const auto& q = p.queues[cell];
    const auto& rs = p.run_starts[cell];
    std::vector<event_span> spans;
    spans.reserve(rs.size());
    for (std::size_t r = 0; r < rs.size(); ++r) {
        auto b = q.data() + rs[r];
        auto e = (r + 1 < rs.size())? q.data() + rs[r + 1] : q.data() + q.size();
        spans.emplace_back(b, e);
    }
    return spans;
}

void add_counters(benchmark::State& state, const payload& p) {
    // Throughput counters (accumulated across iterations; google-benchmark
    // reports per-second rates from these). Shape is a data property, not a
    // rate: report it once (see generate_payload) rather than as a counter.
    state.SetItemsProcessed(static_cast<std::int64_t>(p.total_events));
    state.SetBytesProcessed(static_cast<std::int64_t>(p.total_events * sizeof(spike_event)));
}

// Merge all runs of cell `cell` (spans must point into a *copy* of the
// cell's queue that the merge consumes) into a sorted result.
pse_vector run_merge_one(const payload& p, std::size_t cell, int kind) {
    const auto& orig = p.queues[cell];
    // 0 or 1 run: already key-sorted, nothing to merge. (Also keeps
    // tree_merge_events away from a 0-lane tourney_tree, which is
    // undefined.)
    if (orig.size() <= 1 || p.run_starts[cell].size() <= 1) return orig;
    pse_vector q = orig; // copy; merges advance the span iterators
    auto spans = make_run_spans(p, cell);
    for (auto& s: spans) {
        // Re-point the spans at the copied data.
        s = event_span{q.data() + (s.left - orig.data()),
                       q.data() + (s.right - orig.data())};
    }
    pse_vector out;
    out.reserve(q.size());
    switch (kind) {
        case 0: tree_merge_events(spans, out); break;
        case 1: pqueue_merge_events(spans, out); break;
        case 2: linear_merge_events(spans, out); break;
        default: throw std::runtime_error("unknown run_merge kind");
    }
    return out;
}

} // namespace

// One benchmark function for all sort candidates, selected via range(3).
// Kinds: 0 = std::sort, 1 = ska_sort, 2 = run_merge (tree).
static void BM_sort(benchmark::State& state) {
    const auto num_local_cells = static_cast<cell_size_type>(state.range(0));
    const auto fan_in          = static_cast<std::size_t>(state.range(1));
    const auto num_domains     = static_cast<std::size_t>(state.range(2));
    const auto kind            = static_cast<int>(state.range(3));

    const payload p = generate_payload(num_local_cells, fan_in, num_domains);
    add_counters(state, p);

    while (state.KeepRunning()) {
        for (std::size_t c = 0; c < p.queues.size(); ++c) {
            auto q = p.queues[c]; // in-place sorts modify the copy
            switch (kind) {
            case 0:
                std::sort(
                    q.begin(), q.end(), [](auto& a, auto& b) { return full_key(a) < full_key(b); });
                break;
            case 1:
                ska_sort(q.begin(), q.end(), [](const auto& o) { return full_key(o); });
                break;
            case 2:
                run_merge_one(p, c, 0);
                break;
            }
            benchmark::ClobberMemory();
        }
    }
}

static void BM_run_merge_pqueue(benchmark::State& state) {
    const auto num_local_cells = static_cast<cell_size_type>(state.range(0));
    const auto fan_in          = static_cast<std::size_t>(state.range(1));
    const auto num_domains     = static_cast<std::size_t>(state.range(2));

    const payload p = generate_payload(num_local_cells, fan_in, num_domains);
    add_counters(state, p);

    while (state.KeepRunning()) {
        for (std::size_t c = 0; c < p.queues.size(); ++c) {
            auto out = run_merge_one(p, c, 1);
            benchmark::ClobberMemory();
        }
    }
}

// std::inplace_merge over the runs, in the order the exchange produced them
// (runs time-sorted): measures how much the partial order is exploited.
static void BM_inplace_merge_presorted(benchmark::State& state) {
    const auto num_local_cells = static_cast<cell_size_type>(state.range(0));
    const auto fan_in          = static_cast<std::size_t>(state.range(1));
    const auto num_domains     = static_cast<std::size_t>(state.range(2));

    const payload p = generate_payload(num_local_cells, fan_in, num_domains);
    add_counters(state, p);

    while (state.KeepRunning()) {
        for (std::size_t c = 0; c < p.queues.size(); ++c) {
            auto q         = p.queues[c];
            const auto& rs = p.run_starts[c];
            for (std::size_t r = 0; r + 1 < rs.size(); ++r) {
                auto mid = q.begin() + rs[r + 1];
                std::inplace_merge(q.begin(), mid, q.end(),
                                   [](auto& a, auto& b) { return full_key(a) < full_key(b); });
            }
            benchmark::ClobberMemory();
        }
    }
}

// Same, but with the runs reversed first (worst case for the merge).
static void BM_inplace_merge_shuffled(benchmark::State& state) {
    const auto num_local_cells = static_cast<cell_size_type>(state.range(0));
    const auto fan_in          = static_cast<std::size_t>(state.range(1));
    const auto num_domains     = static_cast<std::size_t>(state.range(2));

    payload p = generate_payload(num_local_cells, fan_in, num_domains);
    add_counters(state, p);
    shuffle_runs(p);

    while (state.KeepRunning()) {
        for (std::size_t c = 0; c < p.queues.size(); ++c) {
            auto q         = p.queues[c];
            const auto& rs = p.run_starts[c];
            for (std::size_t r = 0; r + 1 < rs.size(); ++r) {
                auto mid = q.begin() + rs[r + 1];
                std::inplace_merge(q.begin(), mid, q.end(),
                                   [](auto& a, auto& b) { return full_key(a) < full_key(b); });
            }
            benchmark::ClobberMemory();
        }
    }
}

static void run_custom_arguments(::benchmark::Benchmark* b) {
    for (auto num_local_cells: {256, 1024, 4096}) {
        for (auto fan_in: {8, 32, 128}) {
            for (auto num_domains: {1, 4, 16}) {
                b->Args({num_local_cells, fan_in, num_domains, 0});
                b->Args({num_local_cells, fan_in, num_domains, 1});
                b->Args({num_local_cells, fan_in, num_domains, 2});
                b->Args({num_local_cells, fan_in, num_domains, 3});
            }
        }
    }
}

BENCHMARK(BM_sort)->Apply(run_custom_arguments)->Unit(benchmark::kMillisecond);

static void run_merge_arguments(::benchmark::Benchmark* b) {
    for (auto num_local_cells: {256, 1'024, 4'096}) {
        for (auto fan_in: {8, 32, 128}) {
            for (auto num_domains: {1, 4, 16}) b->Args({num_local_cells, fan_in, num_domains});
        }
    }
}

BENCHMARK(BM_run_merge_pqueue)->Apply(run_merge_arguments)->Unit(benchmark::kMillisecond);
BENCHMARK(BM_inplace_merge_presorted)->Apply(run_merge_arguments)->Unit(benchmark::kMillisecond);
BENCHMARK(BM_inplace_merge_shuffled)->Apply(run_merge_arguments)->Unit(benchmark::kMillisecond);

BENCHMARK_MAIN();
